	for _, r := range []*Raft{raftB, raftC, raftE} {
		rc := r.ReloadableConfig()
		rc.HeartbeatTimeout = 3 * time.Second
		rc.ElectionTimeout = 3 * time.Second
		if err := r.ReloadConfig(rc); err != nil {
			t.Fatalf("reload: %v", err)
		}
	}

