// into the captured package for execution.
func partialLeaderAmong(rs []*Raft, d time.Duration) int {
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		for i, r := range rs {
			if r.State() == Leader {
				return i
			}
		}
		time.Sleep(5 * time.Millisecond)
	}
	return -1
}

func partialAllConfigured(rs []*Raft, want int, d time.Duration) bool {
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		ok := true
		for _, r := range rs {
			f := r.GetConfiguration()
			if err := f.Error(); err != nil || len(f.Configuration().Servers) != want {
				ok = false
				break
			}
		}
		if ok {
			return true
		}
		time.Sleep(10 * time.Millisecond)
	}
	return false
}

func partialConfigSizes(rs []*Raft) []int {
	out := make([]int, 0, len(rs))
	for _, r := range rs {
		f := r.GetConfiguration()
		if err := f.Error(); err != nil {
			out = append(out, -1)
			continue
		}
		out = append(out, len(f.Configuration().Servers))
	}
	return out
}

func partialFullConfigCount(rs []*Raft, want int) int {
	n := 0
	for _, r := range rs {
		f := r.GetConfiguration()
		if err := f.Error(); err == nil && len(f.Configuration().Servers) == want {
			n++
		}
	}
	return n
}

